diff --git a/recreate/check.js b/recreate/check.js
new file mode 100644
index 000000000..b72053959
--- /dev/null
+++ b/recreate/check.js
@@ -0,0 +1,28 @@
+// Check for the "type assertion regression" report: the exact code from the report
+// (wrapper-assertion.ts) must give `type Test = { prop1: "hello"; }`.
+// Exits 1 while the bug is present, 0 once fixed.
+// Usage (from repo root):  node recreate/check.js
+// Override the compiler under test with TS_PATH=/path/to/typescript.js
+const path = require("path");
+const ts = require(process.env.TS_PATH || path.join(__dirname, "../built/local/typescript.js"));
+
+const file = path.join(__dirname, "wrapper-assertion.ts");
+const program = ts.createProgram([file], { strict: true, target: ts.ScriptTarget.ESNext, noEmit: true, types: [] });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+
+let testType;
+sf.forEachChild(n => {
+    if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") testType = checker.getTypeAtLocation(n.name);
+});
+
+const expected = `{ prop1: "hello"; }`;
+const actual = checker.typeToString(testType, undefined, ts.TypeFormatFlags.NoTruncation);
+console.log(`TypeScript ${ts.version}`);
+console.log(`expected: type Test = ${expected}`);
+console.log(`actual:   type Test = ${actual}`);
+if (actual !== expected) {
+    console.error("FAIL: Test is not displayed as the unwrapped type");
+    process.exit(1);
+}
+console.log("PASS");
diff --git a/recreate/wrapper-assertion.ts b/recreate/wrapper-assertion.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/recreate/wrapper-assertion.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
